import java.util.*;

public class Main {
    // binding: type name -> names of its constructor dependencies
    static Map<String, List<String>> bindings = new HashMap<>();
    static Map<String, String> singletons = new HashMap<>();
    static Deque<String> stack = new ArrayDeque<>(); // resolution stack

    static String resolve(String type) {
        if (singletons.containsKey(type)) return singletons.get(type);
        if (stack.contains(type)) {
            List<String> path = new ArrayList<>(stack);
            Collections.reverse(path);          // oldest first
            path.add(type);
            throw new IllegalStateException("cycle detected: " + String.join(" -> ", path));
        }
        stack.push(type);
        List<String> parts = new ArrayList<>();
        for (String dep : bindings.get(type)) parts.add(resolve(dep)); // resolve parameters first
        stack.pop();
        String obj = parts.isEmpty() ? type : type + "(" + String.join(",", parts) + ")";
        singletons.put(type, obj);              // cache as singleton
        return obj;
    }

    public static void main(String[] args) {
        bindings.put("Service", List.of("Repo", "Mailer"));
        bindings.put("Repo", List.of("Db"));
        bindings.put("Db", List.of());
        bindings.put("Mailer", List.of());
        bindings.put("A", List.of("B"));
        bindings.put("B", List.of("A"));
        System.out.println("resolved: " + resolve("Service"));
        try { resolve("A"); }
        catch (IllegalStateException e) { System.out.println(e.getMessage()); }
    }
}

