#include <bits/stdc++.h>
using namespace std;

// binding: type name -> names of its constructor dependencies
map<string, vector<string>> bindings = {
    {"Service", {"Repo", "Mailer"}}, {"Repo", {"Db"}}, {"Db", {}}, {"Mailer", {}},
    {"A", {"B"}}, {"B", {"A"}}};
map<string, string> singletons;
vector<string> stk;  // resolution stack

string resolve(const string& t) {
    if (singletons.count(t)) return singletons[t];
    if (find(stk.begin(), stk.end(), t) != stk.end()) {  // already being built -> cycle
        string path;
        for (auto& s : stk) path += s + " -> ";
        throw runtime_error("cycle detected: " + path + t);
    }
    stk.push_back(t);
    vector<string> parts;
    for (auto& dep : bindings[t]) parts.push_back(resolve(dep));  // parameters first
    stk.pop_back();
    string obj = t;
    if (!parts.empty()) {
        obj += "(";
        for (size_t i = 0; i < parts.size(); i++) obj += (i ? "," : "") + parts[i];
        obj += ")";
    }
    return singletons[t] = obj;  // cache as singleton
}

