using System;
using System.Collections.Generic;

class Program
{
    // binding: type name -> names of its constructor dependencies
    static Dictionary<string, string[]> bindings = new Dictionary<string, string[]>();
    static Dictionary<string, string> singletons = new Dictionary<string, string>();
    static List<string> stack = new List<string>(); // resolution stack

    static string Resolve(string type)
    {
        if (singletons.ContainsKey(type)) return singletons[type];
        if (stack.Contains(type)) // already being built -> cycle
        {
            List<string> path = new List<string>(stack);
            path.Add(type);
            throw new InvalidOperationException("cycle detected: " + string.Join(" -> ", path));
        }
        stack.Add(type);
        List<string> parts = new List<string>();
        foreach (string dep in bindings[type]) parts.Add(Resolve(dep)); // parameters first
        stack.RemoveAt(stack.Count - 1);
        string obj = parts.Count == 0 ? type : type + "(" + string.Join(",", parts) + ")";
        singletons[type] = obj; // cache as singleton
        return obj;
    }

    static void Main()
    {
        bindings["Service"] = new[] { "Repo", "Mailer" };
        bindings["Repo"] = new[] { "Db" };
        bindings["Db"] = new string[0];
        bindings["Mailer"] = new string[0];
        bindings["A"] = new[] { "B" };
        bindings["B"] = new[] { "A" };
        Console.WriteLine("resolved: " + Resolve("Service"));
        try { Resolve("A"); }
        catch (InvalidOperationException e) { Console.WriteLine(e.Message); }
    }
