public class Main {
    static int storedValue = 100, storedVersion = 1;   // the "database row"

    // Succeeds only if the version is still the one we read (UPDATE ... WHERE version = ?)
    static boolean save(int newValue, int expectedVersion) {
        if (storedVersion != expectedVersion) return false;
        storedValue = newValue;
        storedVersion++;
        return true;
    }

    public static void main(String[] args) {
        int aVal = storedValue, aVer = storedVersion;   // user A reads
        int bVal = storedValue, bVer = storedVersion;   // user B reads the same version
        System.out.println("A saves: " + save(aVal + 10, aVer));
        System.out.println("B saves: " + save(bVal + 20, bVer));
        // B retries: reload, re-run the command on fresh state, save again
        bVal = storedValue; bVer = storedVersion;
        System.out.println("B retry saves: " + save(bVal + 20, bVer));
        System.out.println("final value=" + storedValue + " version=" + storedVersion);
    }
}

