import java.util.*;

public class Main {
    static List<Integer> orders = new ArrayList<>();     // "orders table"
    static List<Integer> outbox = new ArrayList<>();     // outbox table: event ids
    static Set<Integer> sent = new HashSet<>();          // outbox rows marked as sent
    static List<Integer> broker = new ArrayList<>();     // the message broker

    // One "transaction": the order row and its event row are written together
    static void placeOrder(int id) { orders.add(id); outbox.add(id); }

    static void relay(boolean crashBeforeMarkingLast) {
        for (int id : outbox) {
            if (sent.contains(id)) continue;
            broker.add(id);                               // publish
            if (crashBeforeMarkingLast && id == outbox.get(outbox.size() - 1)) return; // crash
            sent.add(id);                                 // mark sent
        }
    }

    public static void main(String[] args) {
        placeOrder(1); placeOrder(2);
        relay(true);   // crashes after publishing event 2, before marking it
        relay(false);  // restart: event 2 is published again (at-least-once)
        System.out.println("broker: " + broker);
        Set<Integer> processed = new HashSet<>();         // consumer dedupe table
        for (int id : broker) {
            if (processed.add(id)) System.out.println("handled event " + id);
            else System.out.println("skipped duplicate event " + id);
        }
        System.out.println("orders=" + orders.size() + " outbox=" + outbox.size());
    }
}

