relay(false); // restart: event 2 is published again (at-least-once)
console.log("broker: [" + broker.join(", ") + "]");
const processed = new Set(); // consumer dedupe table
for (const id of broker) {
  if (!processed.has(id)) { processed.add(id); console.log("handled event " + id); }
